// text helper
async function T(parent, text, x, y, w, o={}) {
  const fam=o.font||'Nunito', sty=o.weight||'Regular';
  await F(fam,sty);
  const n=figma.createText();
  n.fontName={family:fam, style:sty};
  n.characters=text;
  n.x=x; n.y=y; n.resize(w,0);
  n.fills=[{type:'SOLID', color:col(o.color||TEXT)}];
  n.fontSize=o.size||14;
  n.lineHeight={value:o.lh||Math.round((o.size||14)*1.32), unit:'PIXELS'};
  if(o.align) n.textAlignHorizontal=o.align;
  parent.appendChild(n);
  return n;
}
function R(parent,w,h,x,y,fill,rx=0,stroke=null,sw=0){
  const n=figma.createRectangle(); n.resize(w,h); n.x=x; n.y=y;
  if(rx) n.cornerRadius=rx;
  n.fills= fill==='none'?[]:[{type:'SOLID', color:col(fill)}];
  if(stroke){ n.strokes=[{type:'SOLID',color:col(stroke)}]; n.strokeWeight=sw; }
  parent.appendChild(n); return n;
}
