const F = await figma.getNodeById("29:216");
const out=[];
if(F){
  out.push(F.name+" children="+F.children.length);
  function walk(n, depth){
    if(depth>0 && n.type==="TEXT"){
      let t=n.characters.replace(/\n/g," ").slice(0,45);
      if(t.length) out.push("  ".repeat(depth)+t);
      return;
    }
    if("children" in n){ for(const k of n.children){ try{walk(k, depth+1);}catch(e){} } }
  }
  walk(F,0);
} else out.push("no frame");
return {texts: out};

