function dump(item){
  const out=[];
  for(const sub of item.children){
    const inner=[];
    for(const k of (sub.children||[])){
      if(k.type==="TEXT") inner.push("T:"+k.characters.slice(0,50));
      else inner.push(k.type+":"+(k.name||"")+":"+Math.round(k.width)+"x"+Math.round(k.height));
    }
    out.push(sub.name + " => " + inner.join(" ;; "));
  }
  return out;
}
return {item1: dump(home.children.find(c=>c.name==="chat_item_1")), item2: dump(home.children.find(c=>c.name==="chat_item_2"))};

