const ws = await figma.getNodeById("5:2");
await figma.setCurrentPageAsync(ws);
const out={};
function findShells(n, found){
  for(const c of n.children){
    const nm=(c.name||"");
    if(nm.toLowerCase().includes("status")||nm.toLowerCase().includes("home")) found.push(nm);
    if("children" in c){ findShells(c, found); }
  }
}
for(const f of ws.children){
  if(!f.name.includes("_")) continue;
  const found=[];
  findShells(f, found);
  out[f.name]=found;
}
return out;

